content.query:
AbuseIPDB_Blacklist_CL
| where TimeGenerated {TimeRange}
| where AbuseConfidenceScore >= {MinConfidence}
| summarize Count = dcount(IpAddress) by CountryCode
| order by Count desc
| take 15

let BlacklistedIPs = AbuseIPDB_Blacklist_CL
| where TimeGenerated {TimeRange}
| where AbuseConfidenceScore >= {MinConfidence}
| summarize AbuseScore = max(AbuseConfidenceScore) by IpAddress;
SigninLogs
| where TimeGenerated {TimeRange}
| where IPAddress in ((BlacklistedIPs | project IpAddress))
| where ResultType == 0
| join kind=inner BlacklistedIPs on $left.IPAddress == $right.IpAddress
| summarize SuccessfulSignIns = count(), MaxScore = max(AbuseScore) by UserPrincipalName
| order by SuccessfulSignIns desc
| take 15

let BlacklistedIPs = AbuseIPDB_Blacklist_CL
| where TimeGenerated {TimeRange}
| where AbuseConfidenceScore >= {MinConfidence}
| summarize AbuseScore = max(AbuseConfidenceScore) by IpAddress;
DeviceNetworkEvents
| where Timestamp {TimeRange}
| where RemoteIP in ((BlacklistedIPs | project IpAddress))
| join kind=inner BlacklistedIPs on $left.RemoteIP == $right.IpAddress
| summarize Connections = count() by InitiatingProcessFileName
| order by Connections desc
| take 10

let BlacklistedIPs = AbuseIPDB_Blacklist_CL
